import json
from pathlib import Path
from PIL import Image
root=Path("art/production/superior-islands-v1")
biomes=[[0,0,2,1],[0,2,1,2],[0,0,1,2],[0,2,1,2],[0,2,1,2],[0,2,1,0]]
for i in range(1,7):
    folder=root/f"island-{i}"
    names={k:list(json.loads((folder/f"{k}.atlas.json").read_text())["frames"]) for k in ["terrain","props"]}
    bindings={}
    def ref(kind,index,props=False):
        key="props" if props else "terrain"
        value={"asset":f"island-{i}-{key}","frame":names[key][index]}
        if not props: value["tileSize"]=[512,512]
        else:
            im=Image.open(folder/"props.png").convert("RGBA")
            box=(index%3*512,index//3*512,index%3*512+512,index//3*512+512)
            alpha=im.crop(box).getchannel("A").point(lambda a:255 if a>200 else 0).getbbox()
            value.update(fit="contain",origin=[0.5,(alpha[3] if alpha else 512)/512])
        bindings[f"{'object' if props else 'terrain'}.island-{i}.{kind}"]=value
    for b,idx in enumerate(biomes[i-1]): ref(f"biome-{b}",idx)
    for kind,idx in [("road",3),("plaza",3),("shore",4),("lava" if i==6 else "water",5)]: ref(kind,idx)
    for kind,idx in [("tree",0),("flora",1),("rock",1 if i in [3,6] else 2),("landmark",3),("arch",4),("cargo",5)]: ref(kind,idx,True)
    pack={"schemaVersion":1,"id":f"superior-island-{i}-art","version":"1.0.0","previewOnly":True,
      "assets":[{"id":f"island-{i}-{key}","kind":"atlas","version":"1.0.0","url":f"{key}.png",
      "atlasUrl":f"{key}.atlas.json","width":1536,"height":1024} for key in ["terrain","props"]],"renderBindings":bindings}
    (folder/"runtime-pack.json").write_text(json.dumps(pack,indent=2)+"\n")
